const ELEMENT_PROP_KEYS = new Set(["text","drafts","layers","depth","fontSize","fontWeight","color","accentColor","backgroundColor","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  text: "Form",
  drafts: "Idea | Maybe | Try | Almost | Again | Closer",
  layers: 16,
  depth: 100,
  fontSize: 220,
  fontWeight: "600",
  color: "#302b26",
  accentColor: "#a800b7",
  backgroundColor: "#eeeae2",
  speed: 1,
};

type TypeFossilElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof TypeFossilBase>;

const TypeFossilInner = forwardRef<
  HTMLDivElement,
  TypeFossilElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<TypeFossil>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <TypeFossilBase
          {...(componentProps as unknown as ComponentProps<typeof TypeFossilBase>)}
        />
      </div>
    </Sequence>
  );
});

export const TypeFossil = Interactive.withSchema({
  Component: TypeFossilInner,
  componentName: "<TypeFossil>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
